import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { createJiti } from "jiti";

const jiti = createJiti(import.meta.url, { alias: { "@": resolve(".") } });
const policy = await jiti.import(resolve("lib/ai/evidence-policy.ts"));
const contacts = await jiti.import(resolve("lib/ai/contact-intelligence.ts"));
const customerAnalysis = await jiti.import(resolve("lib/ai/customer-analysis.ts"));
const runner = await jiti.import(resolve("lib/ai/run-customer-analysis.ts"));
const web = await jiti.import(resolve("lib/ai/web-enrichment.ts"));
const errors = await jiti.import(resolve("lib/ai/error-normalization.ts"));
const presentation = await jiti.import(resolve("lib/ai/presentation.ts"));
const source = (file) => readFileSync(resolve(file), "utf8");
let passed = 0;
const test = (name, fn) => { fn(); passed += 1; process.stdout.write(`✓ ${name}\n`); };
const evidence = (fact, kind="支持", channel="website", url="https://shop.example.com/services/repair") => ({ sourceId:`S${passed}`, channel, sourceUrl:url, fact, kind, confidence:96 });
const gate = (overrides={}) => policy.evaluateEvidenceGate({ strategy:"SMART", identityStatus:"MATCHED", identityConfidence:96, industryConfidence:96, decisionConfidence:96, score:82, industry:"MOBILE_PHONE_REPAIR_SHOP", evidence:[evidence("官网明确提供手机换屏和电池更换服务")], hasCriticalConflict:false, ...overrides });

test("01 只卖手机成品不判维修店",()=>assert.equal(policy.primaryIndustryFor("手机成品零售"),"MOBILE_PHONE_RETAILER"));
test("02 运营商营业厅单独分类",()=>assert.equal(policy.primaryIndustryFor("运营商营业厅"),"MOBILE_NETWORK_OPERATOR_STORE"));
test("03 外配件零售与内配件分离",()=>assert.equal(policy.primaryIndustryFor("手机外配件零售"),"MOBILE_ACCESSORY_RETAILER"));
test("04 维修店不自动映射批发商",()=>assert.notEqual(policy.primaryIndustryFor("手机维修店"),"MOBILE_REPAIR_PARTS_WHOLESALER"));
test("05 普通电脑维修与Apple维修分离",()=>assert.notEqual(policy.primaryIndustryFor("电脑维修店"),"APPLE_DEVICE_REPAIR_SHOP"));
test("06 明确换屏换电池是强直接证据",()=>assert.equal(policy.evidenceStrengthFor(evidence("官网明确提供手机换屏和电池更换服务")),"STRONG_DIRECT"));
test("07 只有原始标签归UNKNOWN",()=>assert.equal(policy.primaryIndustryFor("其他"),"UNKNOWN"));
test("08 无外部证据不得自动开发",()=>assert.equal(gate({evidence:[]}).automationStatus,"AUTO_HOLD"));
test("09 Google候选按匹配分排序而非首条",()=>assert.match(source("lib/ai/web-enrichment.ts"),/scoreDetails[\s\S]*sort\(\(a, b\) => b\.score - a\.score\)/));
test("10 社媒登录页不能成为证据",()=>assert.match(source("lib/ai/web-enrichment.ts"),/社媒登录页或Cookie页/));
test("11 官网新电话可标准化",()=>assert.equal(contacts.normalizePhoneInternational("020 7946 0958","GB"),"+442079460958"));
test("12 地图国际电话保持E164",()=>assert.equal(contacts.normalizePhoneInternational("+34 641 58 19 81","ES"),"+34641581981"));
test("12a 官网tel链接优先保留页面实际展示的本地号码格式",()=>{const phones=web.extractPhones('<a href="tel:+4960214547590">06021 4547 590</a>');assert.equal(phones[0],"06021 4547 590");assert.equal(contacts.normalizePhoneInternational(phones[0],"DE"),"+4960214547590");});
test("13 新电话不覆盖原值而标记新增",()=>assert.equal(contacts.buildContactCandidate({type:"PHONE",value:"+34641581981",country:"ES",sourceChannel:"website",sourceUrl:"https://a.es/contact",identityStatus:"MATCHED",originalValues:["+34600000000"]}).verificationStatus,"NEW_VERIFIED"));
test("14 官网地图多个官方电话均保留来源",()=>{const a=contacts.buildContactCandidate({type:"PHONE",value:"+34611111111",country:"ES",sourceChannel:"website",sourceUrl:"https://a.es/contact",identityStatus:"MATCHED",originalValues:[]});const b=contacts.buildContactCandidate({type:"PHONE",value:"+34622222222",country:"ES",sourceChannel:"google_maps",sourceUrl:"https://google.com/maps/place/a",identityStatus:"MATCHED",originalValues:[]});const r=contacts.reconcileContacts([a,b]);assert.equal(r.contacts.length,2);assert.ok(r.contacts.every(x=>x.verificationStatus==="NEW_VERIFIED"));});
test("14B 未核实候选联系方式不得成为推荐联系方式",()=>{const item=contacts.buildContactCandidate({type:"PHONE",value:"+35312447391",country:"IE",sourceChannel:"google_maps",sourceUrl:"https://google.com/maps/search/wrong",identityStatus:"AMBIGUOUS",originalValues:[]});const r=contacts.reconcileContacts([item]);assert.equal(item.verificationStatus,"UNVERIFIED");assert.equal(r.preferred,null);});
test("15 同类同值联系方式跨来源去重",()=>{const a=contacts.buildContactCandidate({type:"WHATSAPP",value:"+49 171 2345678",country:"DE",sourceChannel:"website",sourceUrl:"https://a.de/contact",identityStatus:"MATCHED",originalValues:[]});const b=contacts.buildContactCandidate({type:"WHATSAPP",value:"0049 171 2345678",country:"DE",sourceChannel:"website",sourceUrl:"https://a.de/impressum",identityStatus:"MATCHED",originalValues:[]});assert.equal(contacts.reconcileContacts([a,b]).contacts.length,1);});
test("16 新邮箱记录准确来源",()=>assert.equal(contacts.buildContactCandidate({type:"EMAIL",value:"sales@a.es",sourceChannel:"website",sourceUrl:"https://a.es/contact",identityStatus:"MATCHED",originalValues:[]}).sourceUrl,"https://a.es/contact"));
test("17 示例邮箱被拒绝",()=>assert.equal(contacts.normalizeEmailStrict("sales@example.com"),""));
test("17a 拼错的模板示例邮箱被拒绝",()=>assert.equal(contacts.normalizeEmailStrict("info@examplde.de"),""));
test("17b 顺序占位电话号码被拒绝",()=>assert.equal(contacts.normalizePhoneInternational("+49 0123456789","DE"),""));
test("17c 历史已保存的无效标准化联系方式仍会在读取时剔除",()=>{const rows=contacts.dedupeVerifiedContactRows([{type:"EMAIL",value_raw:"info@examplde.de",value_normalized:"info@examplde.de",source_channel:"website",verification_status:"NEW_VERIFIED"},{type:"PHONE",value_raw:"+490123456789",value_normalized:"+490123456789",source_channel:"website",verification_status:"NEW_VERIFIED"},{type:"EMAIL",value_raw:"sales@real.de",value_normalized:"sales@real.de",source_channel:"website",verification_status:"NEW_VERIFIED"}]);assert.equal(rows.length,1);assert.equal(rows[0].value_raw,"sales@real.de");});
test("18 普通电话不自动判WhatsApp",()=>assert.match(source("lib/ai/web-enrichment.ts"),/extractWhatsapps/));
test("19 依据页显眼显示新联系方式",()=>assert.match(source("components/ai-screening/evidence-view.tsx"),/VerifiedContactsSection/));
test("20 状态同时有文字和图标",()=>{const s=source("components/ai-screening/evidence-sections.tsx");assert.match(s,/AI已核验的联系方式/);assert.match(s,/已核验的原有资料/);assert.match(s,/AI新发现并已核验/);assert.match(s,/CheckCircle2/);});
test("21 联系方式支持复制和来源链接",()=>{const s=source("components/ai-screening/evidence-sections.tsx");assert.match(s,/navigator\.clipboard\.writeText/);assert.match(s,/核对发现来源|打开来源核验/);});
test("21A 新联系方式必须直接显示具体来源渠道",()=>{const s=source("components/ai-screening/evidence-sections.tsx");assert.match(s,/title=\{`来源：\$\{label\}`\}/);assert.match(s,/谷歌地图商家页/);assert.match(s,/企业官网/);});
test("21B 官网403时仅重试同域协议和www变体",()=>{assert.deepEqual(web.websiteUrlCandidates("http://www.idflmobile.com/"),["http://www.idflmobile.com/","https://www.idflmobile.com/","https://idflmobile.com/"]);const s=source("lib/ai/web-enrichment.ts");assert.match(s,/for \(const candidate of candidates\)/);assert.match(s,/BROWSER_HEADERS/);});
test("21C 官网成功变体必须成为证据与联系方式的真实来源网址",()=>{const s=source("lib/ai/run-customer-analysis.ts");assert.match(s,/const resolvedSourceUrl = channel === "website"/);assert.match(s,/source_url: resolvedSourceUrl/);});
test("21D 官网重要页面优先服务分类页而非单个商品详情",()=>assert.match(source("lib/ai/web-enrichment.ts"),/detailPagePenalty[\s\S]*product\|item\|sku/));
test("22 缓存复用保留原证据时间",()=>assert.match(source("lib/ai/run-customer-analysis.ts"),/captured_at: source\.captured_at \|\| source\.fetched_at \|\| cache\.original_captured_at/));
test("23 客户数据变化使缓存签名变化",()=>{const s=source("lib/ai/reuse-cache.ts");for(const field of ["company_name","phone","email","website","google_url","linkedin_url","facebook_url","instagram_url"])assert.match(s,new RegExp(field));assert.match(s,/source_signature/);});
test("24 海关同名不得直接归属",()=>assert.match(source("lib/ai/customer-analysis.ts"),/身份匹配的海关记录/));
test("25 海关查询不得阻塞基础分析",()=>assert.doesNotMatch(source("lib/ai/run-customer-analysis.ts"),/await\s+collectCustoms/));
test("26 智能模式只综合全部证据调用一次模型",()=>{const s=source("lib/ai/run-customer-analysis.ts");assert.match(s,/run\("all_available_sources"/);assert.doesNotMatch(s,/all_available_sources_retry/);});
test("27 深度模式单条强直接证据可完成行业判断",()=>assert.equal(gate({strategy:"DEEP"}).automationStatus,"AUTO_DEVELOP"));
test("28 暂停继续跳过已完成客户",()=>assert.match(source("workflows/ai-screening.ts"),/\.eq\("status", "PENDING"\)/));
test("29 报告数据来自数据库结果",()=>assert.match(source("app/api/ai/results/route.ts"),/ai_screening_results/));
test("30 无证据VALID为0",()=>assert.notEqual(policy.compatibilityTargetDecision(gate({evidence:[]}).automationStatus),"VALID"));
test("31 无证据INVALID为0",()=>assert.notEqual(policy.compatibilityTargetDecision(gate({evidence:[]}).automationStatus),"INVALID"));
test("32 主体匹配后的Google具体维修分类属于直接公开经营证据",()=>assert.equal(policy.evidenceStrengthFor(evidence("Google商家页明确分类为手机维修店","支持","google_maps","https://www.google.com/maps/place/demo")),"STRONG_DIRECT"));
test("33 不再存在整客户30秒硬超时",()=>{const runner=source("lib/ai/run-customer-analysis.ts");const workflow=source("workflows/ai-screening.ts");assert.doesNotMatch(runner,/timeoutController\.abort\(\), 30_000/);assert.doesNotMatch(workflow,/Promise\.race\(\[analysis, deadline\]\)/);});
test("34 单一Google维修分类不得自动评级",()=>{const result=customerAnalysis.groundCustomerAnalysis({customer_name:"测试维修店",country:"EC",google_url:"https://www.google.com/maps/place/test",evidence:{google_place:{configured:false,name:"测试维修店",types:["手机维修店"],reviews:[],identity_status:"MATCHED",identity_confidence:96,business_status:"OPERATIONAL",verified_google_maps_url:"https://www.google.com/maps/place/test"}}},{industry_type:"手机维修店",is_target_customer:true,ai_score:88,ai_level:"A",ai_reason:"公开信息显示该商家提供手机维修服务。",business_relevance:"提供手机维修服务。",customer_value:"可能采购手机维修配件。",followup_suggestion:"联系确认配件需求。",confidence_score:95,evidence_sufficiency:"充分",evidence_conflicts:[],score_breakdown:{entity_consistency:95,company_authenticity:90,business_activity:90,mobile_parts_match:90,macbook_parts_match:0,wholesale_import_distribution:20,repair_business_match:95,bulk_purchase_potential:60,contactability:80,evidence_completeness:75,contradiction_risk:0},suggested_contact_order:[],evidence_summaries:[]});assert.equal(result.is_target_customer,false);assert.equal(result.ai_level,"D");assert.ok(result.ai_score<60);});
test("35 主体精确匹配的具体Google维修分类可以形成基础评分",()=>{const result=runner.deterministicAnalysis({id:"c1",company_name:"Phone Fix",country:"ES",phone:"+34123456789",google_url:"https://www.google.com/maps/place/phone-fix"},[{channel:"google_maps",status:"COLLECTED",source_url:"https://www.google.com/maps/place/phone-fix",evidence:{configured:false,name:"Phone Fix",phone:"+34123456789",types:["mobile_phone_repair_shop"],reviews:[],identity_status:"MATCHED",identity_confidence:96,match_signals:["商家名称高度一致","电话号码一致"],verified_google_maps_url:"https://www.google.com/maps/place/phone-fix"}}]);assert.ok(result);assert.equal(result.is_target_customer,true);assert.ok(result.ai_score>=60);});
test("36 PostgREST对象错误不会退化为object Object",()=>{const result=errors.normalizeError({code:"PGRST204",message:"schema cache缺少字段",details:"column missing",hint:"reload"},{stage:"CUSTOMER_WRITEBACK"});assert.equal(result.error_code,"PGRST204");assert.match(result.error_message,/schema cache/);assert.doesNotMatch(result.error_message,/object Object/);});
test("36a 非法UTF代理字符在写入前必须安全替换",()=>{const safe=errors.jsonSafe({value:"ok\uDC00bad",nested:["\uD800"]});assert.equal(safe.value,"ok�bad");assert.equal(safe.nested[0],"�");});
test("37 证据与客户写回成功后才原子完成",()=>{const s=source("lib/ai/run-customer-analysis.ts");assert.match(s,/is_latest_valid: false,[\s\S]*writeback_status: "PENDING"/);assert.match(s,/ai_screening_evidence[\s\S]*customers[\s\S]*writeback_status: "COMPLETED"/);assert.doesNotMatch(s,/status: "COMPLETED", analysis_status: "COMPLETED", writeback_status: "PENDING"/);});
test("38 任务统计以模型调用表为费用真值",()=>assert.match(source("supabase/migrations/202608240003_ai_screening_pipeline_v3.sql"),/case when c\.call_count > 0 then c\.total_cost_usd/));
test("39 完整分析不再默认启用网页搜索，仅轻量寻址函数可搜索",()=>{const s=source("lib/ai/customer-analysis.ts");assert.match(s,/discoverPublicSourceUrls/);assert.doesNotMatch(s,/const recoveryTools/);});
test("40 不确定时只综合已采集证据一次且模型调用按客户全程限额",()=>{const s=source("lib/ai/run-customer-analysis.ts");assert.match(s,/existingModelCalls/);assert.match(s,/model_call_baseline/);assert.match(s,/remainingModelCalls/);assert.match(s,/const maxModelCalls = 1/);assert.match(s,/already-collected target-adjacent evidence/);assert.doesNotMatch(s,/const focus = "comprehensive"|public_source_recovery_/);});
test("40a Google或官网已有明确结论时禁止再次调用模型",()=>{const conclusive={is_target_customer:false,confidence_score:96,evidence_sufficiency:"充分",evidence_summaries:[{channel:"website",confidence:96,evidence_type:"矛盾"}],usage:{model:"RULE_ENGINE"}};assert.equal(runner.shouldUseModelSupplement({company_name:"Smoke Shop"},[],conclusive),false);assert.equal(runner.shouldUseModelSupplement({company_name:"Ordinary Business"},[],null),false);assert.equal(runner.shouldUseModelSupplement({company_name:"Phone Repair"},[],null),true);});
test("40b 社媒必须逐个采集并在足够证据后停止",()=>{const s=source("lib/ai/run-customer-analysis.ts");assert.match(s,/const secondaryPriority:[\s\S]*\["facebook", "instagram", "linkedin", "tiktok", "other"\]/);assert.match(s,/for \(const channel of secondaryChannels\)/);assert.doesNotMatch(s,/secondaryChannels\.slice\(index, index \+ 2\)/);assert.match(s,/停止继续采集/);});
test("40c 已确认Facebook经营证据可直接形成结论而无需模型",()=>{const customer={id:"social-1",company_name:"Repair One",country:"DE",phone:"+491701234567",website:"https://repair-one.example"};const records=[{channel:"website",status:"COLLECTED",source_url:"https://repair-one.example",evidence:{url:"https://repair-one.example",reachable:true,title:"Repair One",description:"Contact us",structured_types:[],structured_descriptions:[],headings:[],text_excerpt:"Repair One +49 170 1234567",social_urls:["https://facebook.com/repairone"],pages:[],image_alts:[],image_urls:[],emails:[],phones:["+491701234567"]}},{channel:"facebook",status:"COLLECTED",source_url:"https://facebook.com/repairone",evidence:{url:"https://facebook.com/repairone",reachable:true,title:"Repair One",description:"Phone repair, screen replacement and battery replacement",structured_types:[],structured_descriptions:[],headings:["Phone repair"],text_excerpt:"iPhone screen replacement and battery replacement",social_urls:[],pages:[],image_alts:[],image_urls:[],emails:[],phones:["+491701234567"]}}];const result=runner.deterministicAnalysis(customer,records);assert.ok(result);assert.equal(result.is_target_customer,true);assert.equal(result.usage.model,"RULE_ENGINE");assert.equal(runner.isConclusiveChannelAnalysis(result),true);assert.equal(runner.shouldUseModelSupplement(customer,records,result),false);});
test("40d 已匹配Google手机维修类目可直接确认而无需模型",()=>{const customer={id:"phone-review",company_name:"PhonenPhone",country:"IE",phone:"+35310000000",google_url:"https://google.com/maps/place/phonenphone"};const records=[{channel:"google_maps",status:"COLLECTED",source_url:"https://google.com/maps/place/phonenphone",evidence:{name:"PhonenPhone",phone:"+35310000000",types:["mobile_phone_repair_shop"],reviews:["Speedy repair and friendly service"],identity_status:"MATCHED",identity_confidence:100,match_signals:["商家名称高度一致","电话信息一致"],verified_google_maps_url:"https://google.com/maps/place/phonenphone"}}];const result=runner.deterministicAnalysis(customer,records);assert.ok(result);assert.equal(result.industry_type,"手机维修店");assert.equal(result.is_target_customer,true);assert.ok(result.ai_score>=60);assert.equal(result.usage.model,"RULE_ENGINE");const finalized=runner.finalizeAnalysisAgainstEvidence(customer,records,result);assert.equal(finalized.industry_type,"手机维修店");assert.equal(finalized.is_target_customer,true);assert.ok(finalized.ai_score>=60);});
test("40d2 Google评论明确电子设备和游戏机维修不会在最终归一化时丢失",()=>{const customer={id:"dd-tech",company_name:"D&D Tech Repairs",country:"IE",phone:"+35310000001",google_url:"https://google.com/maps/place/dd-tech"};const records=[{channel:"google_maps",status:"COLLECTED",source_url:"https://google.com/maps/place/dd-tech",evidence:{name:"D&D Tech Repairs",phone:"+35310000001",types:["electronics_repair_shop"],reviews:["Fast PS5 HDMI repair and Xbox console repair"],identity_status:"MATCHED",identity_confidence:100,match_signals:["商家名称高度一致","地址信息一致","电话号码一致"],verified_google_maps_url:"https://google.com/maps/place/dd-tech"}}];const result=runner.deterministicAnalysis(customer,records);assert.ok(result);const finalized=runner.finalizeAnalysisAgainstEvidence(customer,records,result);assert.equal(finalized.industry_type,"其他维修行业");assert.equal(finalized.is_target_customer,true);assert.ok(finalized.ai_score>=60);});
test("40e 第三方企业目录不得冒充客户官网",()=>{const customer={id:"directory",company_name:"World mobile reparasjon",country:"NO",phone:"+4712345678"};for(const url of ["https://www.fastbase.com/countryindex/Norway/M/Mobile-phone-repair-shop","https://mobilverksteder.com/oslo/fix-my-phone-oslo/"]){const record={channel:"website",status:"COLLECTED",source_url:url,evidence:{url,reachable:true,title:"Mobile phone repair directory",description:"Business listings",structured_names:[],structured_descriptions:[],headings:[],text_excerpt:"World mobile reparasjon",image_alts:[],image_urls:[],emails:[],phones:[]}};assert.equal(runner.websiteRecordMatchesEntity(customer,[],record),false);}});
test("41 余额耗尽属于不可重试错误",()=>assert.equal(errors.normalizeError({status:429,code:"credit_balance_exhausted",message:"余额不足"},{stage:"MODEL_CALL"}).retryable,false));
test("42 智能模式输入证据有严格长度上限",()=>{const compact=runner.evidenceForModel([{channel:"website",status:"COLLECTED",source_url:"https://a.example",evidence:{url:"https://a.example",reachable:true,title:"测试企业",description:"业务".repeat(1000),headings:Array(20).fill("手机维修"),text_excerpt:"维修换屏".repeat(4000),image_alts:Array(20).fill("维修门店"),image_urls:Array(20).fill("https://a.example/image.jpg"),video_urls:Array(10).fill("https://a.example/video.mp4"),emails:[],phones:[],pages:Array(8).fill({url:"https://a.example/service",title:"服务",description:"维修".repeat(500),headings:["维修"],text_excerpt:"换屏".repeat(1000),image_alts:[],image_urls:[],emails:[],phones:[]})}}],"fast");assert.ok(JSON.stringify(compact).length<7000);});
test("43 只发送少量关键图片且不发送视频给模型",()=>{const compact=runner.evidenceForModel([{channel:"website",status:"COLLECTED",source_url:"https://a.example",evidence:{url:"https://a.example",reachable:true,headings:[],image_alts:[],image_urls:["https://a.example/image.jpg","https://a.example/image-2.jpg","https://a.example/image-3.jpg"],video_urls:["https://a.example/video.mp4"],emails:[],phones:[]}}],"deep");const text=JSON.stringify(compact);assert.match(text,/image\.jpg/);assert.match(text,/image-2\.jpg/);assert.doesNotMatch(text,/image-3\.jpg|video\.mp4/);});
test("44 本轮无可核验经营事实必须形成低相关结论而不是无限等待",()=>{const s=source("lib/ai/run-customer-analysis.ts");assert.doesNotMatch(s,/deferEvidenceRecovery/);assert.doesNotMatch(s,/return \{ status: "PENDING" as const \}/);assert.match(s,/analysis = insufficientDataAnalysis/);});
