test("46 单客户最多一次大模型补证且仅对不确定结论触发",()=>{const s=source("lib/ai/run-customer-analysis.ts");assert.match(s,/const maxModelCalls = 1/);assert.doesNotMatch(s,/AI_SCREENING_DEEP_MAX_MODEL_CALLS_PER_CUSTOMER|all_available_sources_retry|canRecoverModelCall/);assert.match(s,/analysis\.confidence_score < 82/);});
