test("134 没有真实图片输入时模型声称看见维修工作台不得进入证据",()=>{const input={customer_name:"Visual Claim",country:"GB",google_url:"https://google.com/maps/place/visual",evidence:{google_place:{name:"Visual Claim",types:["store"],identity_status:"MATCHED",identity_confidence:98,verified_google_maps_url:"https://google.com/maps/place/visual",image_urls:[]}}};const raw={industry_type:"手机维修店",is_target_customer:true,ai_score:80,ai_level:"B",ai_reason:"图片证明维修",business_relevance:"相关",customer_value:"目标客户",followup_suggestion:"联系",confidence_score:95,evidence_sufficiency:"充分",evidence_conflicts:[],score_breakdown:{entity_consistency:98,company_authenticity:95,business_activity:90,mobile_parts_match:90,macbook_parts_match:0,wholesale_import_distribution:0,repair_business_match:90,bulk_purchase_potential:50,contactability:50,evidence_completeness:90,contradiction_risk:0},suggested_contact_order:[],evidence_summaries:[{channel:"google_maps",title_zh:"商家图片直接证据",fact_zh:"图片清楚展示维修工作台和正在维修的手机。",source_url:"https://google.com/maps/place/visual",evidence_type:"支持",confidence:95}]};const result=customerAnalysis.groundCustomerAnalysis(input,raw);assert.equal(result.evidence_summaries.some((item)=>/维修工作台/.test(item.fact_zh)),false);assert.equal(result.is_target_customer,false);});
