test("142 四项销售结论引用具体来源标题且外语原文只保留在证据",()=>{const result=runner.deterministicAnalysis({id:"itspot",company_name:"ITspot PC - Laptop - Phone Repair",country:"IE",phone:"353831731107",email:"info@itspot.ie",website:"https://www.itspot.ie/"},[{channel:"website",status:"COLLECTED",source_url:"https://www.itspot.ie/",evidence:{url:"https://www.itspot.ie/",reachable:true,title:"ITspot PC, Laptop & Phone Repair Dublin",description:"Laptop, MacBook, Smartphone, Gaming PC and Console repairs and hardware upgrades.",structured_types:["LocalBusiness"],structured_descriptions:[],headings:["Screen replacement","Battery replacement","Charging port repair"],text_excerpt:"We repair computers, laptops and smartphones. Advanced board and motherboard repair is available.",image_alts:[],image_urls:[],emails:["info@itspot.ie"],phones:["+353831731107"]}}]);assert.ok(result);for(const value of [result.ai_reason,result.business_relevance,result.customer_value]) assert.match(value,/ITspot PC, Laptop & Phone Repair Dublin/);assert.doesNotMatch(result.ai_reason,/关键原文/);assert.match(result.evidence_summaries[0].original_excerpt,/repair|repairs/i);assert.doesNotMatch(result.ai_reason,/官网明确显示：/);});
