test("157 归一化后发现直接维修事实必须重新校准评分和结论",()=>{const customer={id:"active",company_name:"ActiveTek",country:"GB",phone:"447700900001",email:null,website:null,google_url:"https://google.com/maps/place/active"};const records=[{channel:"google_maps",status:"COLLECTED",source_url:"https://google.com/maps/place/active",evidence:{name:"ActiveTek",types:["computer_repair_service"],description:"Computer and laptop repair service",reviews:[],identity_status:"MATCHED",identity_confidence:100,match_signals:["商家名称高度一致","地址信息一致","电话号码一致"],mismatch_signals:[],verified_google_maps_url:"https://google.com/maps/place/active"}}];const finalized=runner.finalizeAnalysisAgainstEvidence(customer,records,{industry_type:"其他",is_target_customer:false,ai_score:23,ai_level:"D",ai_reason:"D级23分",business_relevance:"低相关",customer_value:"低",followup_suggestion:"不开发",confidence_score:40,evidence_sufficiency:"一般",evidence_conflicts:[],score_breakdown:{entity_consistency:100,company_authenticity:75,business_activity:60,mobile_parts_match:0,macbook_parts_match:0,wholesale_import_distribution:0,repair_business_match:0,bulk_purchase_potential:0,contactability:70,evidence_completeness:25,contradiction_risk:45},suggested_contact_order:[],evidence_summaries:[{channel:"google_maps",title_zh:"Google商家",fact_zh:"商家公开业务。",source_url:"https://google.com/maps/place/active",evidence_type:"中性",confidence:100}],usage:{model:"RULE_ENGINE",input_tokens:0,cached_input_tokens:0,output_tokens:0,total_tokens:0,cost_usd:0,pricing_snapshot:{}}});assert.equal(finalized.industry_type,"电脑维修店");assert.equal(finalized.is_target_customer,true);assert.ok(finalized.ai_score>=60);assert.notEqual(finalized.ai_level,"D");assert.match(finalized.ai_reason,new RegExp(`${finalized.ai_score}分`));});
test("158 高度可能匹配且无冲突的直接目标证据允许自动开发",()=>{const result=policy.evaluateEvidenceGate({strategy:"SMART",identityStatus:"LIKELY_MATCHED",identityConfidence:80,industryConfidence:80,decisionConfidence:80,score:64,industry:"MOBILE_PHONE_REPAIR_SHOP",evidence:[evidence("Google商家公开说明明确显示：手机维修和屏幕或玻璃更换。","支持","google_maps","https://google.com/maps/place/repair")],hasCriticalConflict:false});assert.equal(result.automationStatus,"AUTO_DEVELOP");});
test("158a 完整地址匹配形成的70分高度可能主体加直接维修证据可自动开发",()=>{const result=policy.evaluateEvidenceGate({strategy:"SMART",identityStatus:"LIKELY_MATCHED",identityConfidence:73,industryConfidence:80,decisionConfidence:80,score:64,industry:"MOBILE_PHONE_REPAIR_SHOP",evidence:[evidence("Google商家近期评论明确显示：手机维修和屏幕或玻璃更换。","支持","google_maps","https://google.com/maps/place/repair")],hasCriticalConflict:false});assert.equal(result.automationStatus,"AUTO_DEVELOP");});
test("159 模糊或冲突主体仍不得凭其他企业维修事实自动开发",()=>{for(const identityStatus of ["AMBIGUOUS","CONFLICTED"]){const result=policy.evaluateEvidenceGate({strategy:"SMART",identityStatus,identityConfidence:72,industryConfidence:90,decisionConfidence:90,score:75,industry:"MOBILE_PHONE_REPAIR_SHOP",evidence:[evidence("候选商家提供手机维修和换屏。","支持","google_maps","https://google.com/maps/place/candidate")],hasCriticalConflict:identityStatus==="CONFLICTED"});assert.notEqual(result.automationStatus,"AUTO_DEVELOP");}});
test("160 明确无关行业证据不得被一致性修复抬为目标客户",()=>{const result=policy.evaluateEvidenceGate({strategy:"SMART",identityStatus:"LIKELY_MATCHED",identityConfidence:82,industryConfidence:90,decisionConfidence:90,score:18,industry:"SOFTWARE_OR_IT_SERVICE",evidence:[evidence("企业官网明确提供IT系统、网络和服务器技术支持。","矛盾","website","https://it.example/services")],hasCriticalConflict:false,explicitRejectEvidence:true});assert.equal(result.automationStatus,"AUTO_REJECT");});
test("161 Google有效维修评论优先进入分析且不遗漏其余可用评论",()=>{const ordered=runner.prioritizeGoogleReviews(["Great service","Changed my iPhone screen and battery","Fast phone repair","Great service",""]);assert.equal(ordered.length,3);assert.match(ordered[0],/screen|repair/i);assert.match(ordered[1],/screen|repair/i);});
test("162 目标行业评分按真实证据强弱拉开而不是统一卡在60分",()=>{const base={industry_type:"手机维修店",is_target_customer:true,ai_score:55,ai_level:"D",ai_reason:"旧结论",business_relevance:"相关",customer_value:"待评估",followup_suggestion:"联系",confidence_score:85,evidence_sufficiency:"充分",evidence_conflicts:[],score_breakdown:{entity_consistency:95,company_authenticity:80,business_activity:45,mobile_parts_match:65,macbook_parts_match:0,wholesale_import_distribution:0,repair_business_match:65,bulk_purchase_potential:20,contactability:70,evidence_completeness:70,contradiction_risk:0},suggested_contact_order:[]};const basic=customerAnalysis.groundCustomerAnalysis({customer_name:"Basic Repair",country:"GB",phone:"+441234",website:"https://basic.example",evidence:{website:{url:"https://basic.example",reachable:true,title:"Basic Repair",headings:[],image_alts:[],image_urls:[],emails:[],phones:[]}}},{...base,evidence_summaries:[{channel:"website",title_zh:"官网",fact_zh:"企业官网明确提供手机维修。",source_url:"https://basic.example/repair",evidence_type:"支持",confidence:95}]});const rich=customerAnalysis.groundCustomerAnalysis({customer_name:"Rich Repair",country:"GB",phone:"+441235",email:"sales@rich.example",website:"https://rich.example",google_url:"https://google.com/maps/place/rich",evidence:{website:{url:"https://rich.example",reachable:true,title:"Rich Repair",headings:[],image_alts:[],image_urls:[],emails:[],phones:[]},google_place:{name:"Rich Repair",types:["mobile_phone_repair_shop"],identity_status:"MATCHED",identity_confidence:98,user_ratings_total:180,verified_google_maps_url:"https://google.com/maps/place/rich"}}},{...base,evidence_summaries:[{channel:"website",title_zh:"官网",fact_zh:"企业官网明确提供手机维修、屏幕或玻璃更换、电池更换和主板或逻辑板维修。",source_url:"https://rich.example/services",evidence_type:"支持",confidence:98},{channel:"google_maps",title_zh:"Google评论",fact_zh:"Google商家近期有效评论明确记录手机维修、屏幕或玻璃更换和电池更换。",source_url:"https://google.com/maps/place/rich",evidence_type:"支持",confidence:96}]});if(!basic.is_target_customer||basic.ai_score<60||!rich.is_target_customer||rich.ai_score<=basic.ai_score)throw new Error(`评分差异异常 basic=${basic.ai_score}/${basic.is_target_customer} rich=${rich.ai_score}/${rich.is_target_customer}`);assert.ok(new Set([basic.ai_score,rich.ai_score]).size===2);});
test("164 主体门槛未通过时不得保留目标行业并压成D级",()=>{const result=runner.reconcileRejectedTargetIndustry({industry_type:"手机维修店",is_target_customer:true,ai_score:76,ai_level:"B",ai_reason:"候选商家提供手机维修",business_relevance:"相关",customer_value:"可开发",followup_suggestion:"联系",confidence_score:70,evidence_sufficiency:"一般",evidence_conflicts:[],score_breakdown:{entity_consistency:45,company_authenticity:60,business_activity:80,mobile_parts_match:80,macbook_parts_match:0,wholesale_import_distribution:0,repair_business_match:85,bulk_purchase_potential:20,contactability:40,evidence_completeness:50,contradiction_risk:70},suggested_contact_order:[],evidence_summaries:[]},"企业主体尚未达到自动判定所需的身份匹配阈值。");assert.equal(result.industry_type,"其他");assert.equal(result.is_target_customer,false);assert.ok(result.ai_score<60);assert.match(result.ai_reason,/不能归属于当前客户/);});
test("165 永久关闭只作为营业状态结论不得冒充所属行业",()=>{const result=runner.reconcileRejectedTargetIndustry({industry_type:"手机维修店",is_target_customer:true,ai_score:82,ai_level:"B",ai_reason:"维修业务",business_relevance:"相关",customer_value:"可开发",followup_suggestion:"联系",confidence_score:90,evidence_sufficiency:"充分",evidence_conflicts:[],score_breakdown:{entity_consistency:95,company_authenticity:90,business_activity:70,mobile_parts_match:80,macbook_parts_match:0,wholesale_import_distribution:0,repair_business_match:90,bulk_purchase_potential:30,contactability:50,evidence_completeness:80,contradiction_risk:50},suggested_contact_order:[],evidence_summaries:[]},"存在永久关闭证据",true);assert.equal(result.industry_type,"其他");assert.match(result.ai_reason,/永久关闭/);assert.equal(result.ai_level,"D");assert.ok(result.ai_score<60);});
test("166 已通过AUTO_DEVELOP门槛的目标行业不得进入拒绝降级逻辑",()=>{const analysis={industry_type:"手机维修店",is_target_customer:true,ai_score:78,ai_level:"B",ai_reason:"已确认维修业务",business_relevance:"相关",customer_value:"可开发",followup_suggestion:"联系",confidence_score:92,evidence_sufficiency:"充分",evidence_conflicts:[],score_breakdown:{entity_consistency:95,company_authenticity:90,business_activity:80,mobile_parts_match:80,macbook_parts_match:0,wholesale_import_distribution:0,repair_business_match:90,bulk_purchase_potential:45,contactability:70,evidence_completeness:85,contradiction_risk:0},suggested_contact_order:[],evidence_summaries:[]};const result=runner.reconcileFinalDecision(analysis,"AUTO_DEVELOP","已确认同一企业，且直接经营证据明确符合目标业务。");assert.equal(result.industry_type,"手机维修店");assert.equal(result.ai_score,78);assert.equal(result.ai_level,"B");assert.equal(result.is_target_customer,true);});
