test("230 已匹配官网联系页的新增邮箱电话必须在分析结论中保留来源链路",()=>{const analysis={ai_reason:"企业官网首页：已核验经营内容：手机维修",followup_suggestion:"优先联系",industry_type:"手机维修店",is_target_customer:true,ai_score:72,ai_level:"B",business_relevance:"相关",customer_value:"可开发",confidence_score:95,evidence_sufficiency:"充分",evidence_conflicts:[],score_breakdown:{},suggested_contact_order:[],evidence_summaries:[],usage:{model:"RULE_ENGINE",model_calls:0,input_tokens:0,cached_input_tokens:0,output_tokens:0,total_tokens:0,cost_usd:0}};const result=runner.applyVerifiedWebsiteContactSummary(analysis,[{type:"EMAIL",valueRaw:"sales@shop.example",valueNormalized:"sales@shop.example",sourceChannel:"website",sourceUrl:"https://shop.example/contact-us",identityStatus:"MATCHED",verificationStatus:"NEW_VERIFIED",contactStatus:"NEW",capturedAt:"2026-09-11",contentHash:"a"},{type:"PHONE",valueRaw:"+353111111",valueNormalized:"+353111111",sourceChannel:"website",sourceUrl:"https://shop.example/contact-us",identityStatus:"MATCHED",verificationStatus:"NEW_VERIFIED",contactStatus:"NEW",capturedAt:"2026-09-11",contentHash:"b"}]);assert.match(result.ai_reason,/官网联系方式核验：已从企业官网（\/contact-us）确认邮箱1个、电话1个/);});
