test("232 已确认运营商与二手手机经营事实不得笼统写为其他",()=>{const base={is_target_customer:false,ai_score:25,ai_level:"D",ai_reason:"",business_relevance:"",customer_value:"",followup_suggestion:"",confidence_score:92,evidence_sufficiency:"充分",evidence_conflicts:[],score_breakdown:{entity_consistency:96,company_authenticity:90,business_activity:60,mobile_parts_match:0,macbook_parts_match:0,wholesale_import_distribution:0,repair_business_match:0,bulk_purchase_potential:0,contactability:60,evidence_completeness:90,contradiction_risk:0},suggested_contact_order:[]};const input={customer_name:"Specific Retail",country:"GB",website:"https://retail.example",evidence:{website:{url:"https://retail.example",reachable:true,title:"Specific Retail",headings:[],image_alts:[],image_urls:[],emails:[],phones:[]}}};const operator=customerAnalysis.groundCustomerAnalysis(input,{...base,industry_type:"其他",evidence_summaries:[{channel:"website",title_zh:"企业官网",fact_zh:"企业官网明确提供手机合约和移动通信套餐。",source_url:"https://retail.example/plans",evidence_type:"支持",confidence:96}]});const refurbished=customerAnalysis.groundCustomerAnalysis(input,{...base,industry_type:"其他",evidence_summaries:[{channel:"website",title_zh:"企业官网",fact_zh:"企业官网明确销售二手手机和翻新iPhone。",source_url:"https://retail.example/used",evidence_type:"支持",confidence:96}]});assert.equal(operator.industry_type,"运营商营业厅");assert.equal(refurbished.industry_type,"二手或翻新手机销售");});
test("233 人工冲突复验允许已评分客户进入任务且必须强制重新采集",()=>{const route=source("app/api/ai/tasks/route.ts");assert.match(route,/reanalysis\?: boolean/);assert.match(route,/const isReanalysis = body\.reanalysis === true/);assert.match(route,/if \(!isReanalysis\) allowedQuery = allowedQuery\.is\("ai_score", null\)/);assert.match(route,/force_fresh_analysis: true, reanalysis_scope: "MANUAL_CONFLICT"/);assert.equal(runner.shouldReuseAnalysisForTask({force_fresh_analysis:true,reanalysis_scope:"MANUAL_CONFLICT"}),false);});
test("234 电信主营页面的泛维修链接不得判为手机维修目标",()=>{const customer={id:"o2",company_name:"o2 Shop",country:"DE",website:"https://o2.example"};const records=[{channel:"website",status:"COLLECTED",source_url:customer.website,evidence:{url:customer.website,reachable:true,title:"o2 Shop",description:"Mobile contracts, SIM cards and broadband plans. Handy Reparatur service information.",structured_types:[],structured_descriptions:[],headings:["Mobile plan and phone contract"],text_excerpt:"Telecommunications service provider and Telekom partner.",image_alts:[],image_urls:[],emails:[],phones:[]}}];const result=runner.deterministicAnalysis(customer,records);assert.ok(result);assert.equal(result.industry_type,"运营商营业厅");assert.equal(result.is_target_customer,false);assert.ok(result.ai_score<60);});
test("235 IT支持与电脑服务不得因泛电脑服务词判为电脑维修",()=>{const customer={id:"tri",company_name:"TRI IT Service",country:"DE",website:"https://tri.example"};const records=[{channel:"website",status:"COLLECTED",source_url:customer.website,evidence:{url:customer.website,reachable:true,title:"IT Service für die Business-Class",description:"Computer technical support, managed IT, network setup and server maintenance.",structured_types:[],structured_descriptions:[],headings:["IT support"],text_excerpt:"Business IT systems and hosting.",image_alts:[],image_urls:[],emails:[],phones:[]}}];const result=runner.deterministicAnalysis(customer,records);assert.ok(result);assert.equal(result.industry_type,"软件或IT服务");assert.equal(result.is_target_customer,false);assert.ok(result.ai_score<60);});
test("236 家电维修与电池服务不得伪造为手机维修或电池更换",()=>{const customer={id:"fairrepair",company_name:"Fairrepair",country:"DE",website:"https://fairrepair.example"};const records=[{channel:"website",status:"COLLECTED",source_url:customer.website,evidence:{url:customer.website,reachable:true,title:"Fairrepair",description:"Repair of household appliances, music systems and electrical appliances. Battery service and 3D printing.",structured_types:[],structured_descriptions:[],headings:["Appliance repair"],text_excerpt:"Home appliance repair service.",image_alts:[],image_urls:[],emails:[],phones:[]}}];const result=runner.deterministicAnalysis(customer,records);assert.ok(result);assert.equal(result.industry_type,"电器或家电维修");assert.equal(result.is_target_customer,false);assert.ok(result.ai_score<60);assert.doesNotMatch(result.evidence_summaries[0].fact_zh,/手机维修|电池更换/);});
test("237 电信主营但同源明确屏幕与电池硬件维修时仍保留目标结论",()=>{const customer={id:"mixed-telecom-repair",company_name:"Mixed Repair",country:"DE",website:"https://mixed.example"};const records=[{channel:"website",status:"COLLECTED",source_url:customer.website,evidence:{url:customer.website,reachable:true,title:"Telecom and repair",description:"Mobile contracts and SIM cards. Our specialist repair workshop replaces iPhone screens, batteries and charging ports.",structured_types:[],structured_descriptions:[],headings:["Screen and battery replacement"],text_excerpt:"Professional smartphone repair workshop.",image_alts:[],image_urls:[],emails:[],phones:[]}}];const result=runner.deterministicAnalysis(customer,records);assert.ok(result);assert.equal(result.is_target_customer,true);assert.ok(result.ai_score>=60);});

